function validate_name(name){
  const patient_name = name.trim();
  if(typeof(patient_name) === "string" && patient_name.length !== 0)
  {
    if(patient_name.length > 2 && patient_name.length <= 50)
    {
       return { 
         name:patient_name,
         valid: true
       };
    }
    return {
      valid:false,
      reason:"Empty Name Received.Ask the user for name."
    };
  }

  return {
    valid: false,
    reason:"Invalid Name received.Ask the user for name."
  };
}

const name = $input.first().json.contacts[0].profile.name || "";

return {
  ...validate_name(name)
};

